def write(path: str = OUT_PATH) -> int:
    canaries = _build()
    with open(path, "w", encoding="utf-8") as f:
        for c_item in canaries:
            f.write(json.dumps(c_item, ensure_ascii=False) + "\n")
    return len(canaries)

