  }

  const loadJobs = async (path: string) => {
    setLoadingList(true)
    setError('')

    try {
      const res = await fetch(`/archives/ibm/jobs${buildQuery(path)}`)
      const data = (await res.json()) as IBMArchiveListResponse | { detail?: string }

      if (!res.ok) {
        throw new Error('detail' in data ? data.detail || 'Failed to load archive jobs' : 'Failed to load archive jobs')
      }

      const response = data as IBMArchiveListResponse
      setJobs(response.jobs)

      if (response.jobs.length > 0) {
        setSelectedJobId((current) => {
          const next = current && response.jobs.some((job) => job.job_id === current)
            ? current
            : response.jobs[0].job_id
          return next
        })
      } else {
        setSelectedJobId('')
        setSelectedJob(null)
      }

      window.localStorage.setItem('qpyth-archive-dir', path.trim())
    } catch (fetchError) {
      console.error(fetchError)
      setJobs([])
      setSelectedJobId('')
      setSelectedJob(null)
      setError(fetchError instanceof Error ? fetchError.message : 'Failed to load IBM archive jobs.')
    } finally {
      setLoadingList(false)
    }
  }

  useEffect(() => {
