(function buildChain() {
  const SVG_NS = 'http://www.w3.org/2000/svg';
  const svg    = document.getElementById('chainSvg');
  const CW     = 560, CH = 155;
  const cols   = 14;               // one column per turn
  const cR     = 18;               // circle radius
  const colW   = CW / cols;        // ~40px per column
  const rowH   = 50;
  const nCols  = Math.ceil((maxTurn + 1) / 3);

  // States grouped by turn
  const byTurn = Array.from({ length: maxTurn + 1 }, () => []);
  states.forEach(s => byTurn[s.turn].push(s));

  byTurn.forEach((turnStates, t) => {
    const col   = t % nCols;
    const row   = Math.floor(t / nCols);
    const cx    = (col + 0.5) * colW;
    const cy    = 28 + row * rowH;

    // Connector to previous column (not first row)
    if (t >= nCols) {
      const prevT   = t - nCols;
      const prevCol  = prevT % nCols;
      const prevRow  = Math.floor(prevT / nCols);
      const px = (prevCol + 0.5) * colW;
      const py = 28 + prevRow * rowH;
      const ln = document.createElementNS(SVG_NS, 'line');
      ln.setAttribute('x1', px); ln.setAttribute('y1', py + cR);
      ln.setAttribute('x2', cx);  ln.setAttribute('y2', cy - cR);
      ln.setAttribute('class', 'connector-line');
      svg.appendChild(ln);
    }

    // Circle
    const circ = document.createElementNS(SVG_NS, 'circle');
    circ.setAttribute('cx', cx); circ.setAttribute('cy', cy);
    circ.setAttribute('r',  cR);
    circ.setAttribute('class', 'chain-circle');
    svg.appendChild(circ);

    // Turn label
    const tl = document.createElementNS(SVG_NS, 'text');
    tl.setAttribute('x', cx); tl.setAttribute('y', cy + cR + 12);
    tl.setAttribute('class', 'chain-label');
    tl.textContent = `turn ${t}`;
    svg.appendChild(tl);

    // State dots at their wrapped angular position
    turnStates.forEach(s => {
      const dr = cR - 4;
      const px = cx + dr * Math.sin(s.phiWrap);
      const py = cy - dr * Math.cos(s.phiWrap);
      const d  = document.createElementNS(SVG_NS, 'circle');
      d.setAttribute('cx', px.toFixed(2)); d.setAttribute('cy', py.toFixed(2));
      d.setAttribute('r', '3');
      d.setAttribute('class', 'chain-dot');
      d.setAttribute('data-n', s.n);
      d.addEventListener('mouseenter', ev => {
        showTip(ev, [
          `n=${s.n}`,
          `turn=${s.turn}`,
          `θ=${s.theta.toFixed(3)} rad`,
          `φ_wrap=${s.phiWrap.toFixed(4)} rad`,
        ]);
      });
      d.addEventListener('mousemove', moveTip);
      d.addEventListener('mouseleave', hideTip);
      svg.appendChild(d);
    });
  });
}());

