def load_jsonl_text(path: str, text_field: str = "text", limit: int | None = None) -> str:
    rows = []
    with open(path, "r", encoding="utf-8") as f:
        for i, line in enumerate(f):
            if limit is not None and i >= limit:
                break
            row = json.loads(line)
            rows.append(row.get(text_field, ""))
    return "\n".join(rows)

